const inc = (n: number): number => n + 1;
const dbl = (n: number): number => n * 2;

const compose =
	<A, B, C>(f: (b: B) => C, g: (a: A) => B) =>
	(a: A): C =>
		f(g(a));

console.log(compose(inc, dbl)(5), compose(dbl, inc)(5));

