type Fn = (n: number) => number;

const pipe =
	(...fns: Fn[]) =>
	(x: number): number =>
		fns.reduce((acc, f) => f(acc), x);

console.log(
	pipe(
		(n) => n + 1,
		(n) => n * 2,
		(n) => n - 3,
	)(4),
);

